import{_ as s,o as t,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Élèves et tuteurs","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/eleves-tuteurs.md","filePath":"src/guide/admin/eleves-tuteurs.md"}'),i={name:"guide/admin/eleves-tuteurs.md"};function n(l,e,o,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="eleves-et-tuteurs" tabindex="-1">Élèves et tuteurs <a class="header-anchor" href="#eleves-et-tuteurs" aria-label="Permalink to &quot;Élèves et tuteurs&quot;">​</a></h1><p>Cette section couvre le dossier d&#39;un élève et tout ce qui s&#39;y rattache : son inscription en classe, ses tuteurs (parents), son éventuel accès personnel au portail élève, et ses matières de spécialité.</p><h2 id="dossiers-eleves" tabindex="-1">Dossiers élèves <a class="header-anchor" href="#dossiers-eleves" aria-label="Permalink to &quot;Dossiers élèves&quot;">​</a></h2><p><strong>Élèves et admissions → Élèves</strong> liste les élèves de l&#39;établissement, avec une recherche par nom (et par matricule, s&#39;il est <a href="./parametres-application.html#fiche-eleve">activé</a>) et un filtre par classe (y compris « Non affecté » pour les élèves sans classe sur l&#39;année en cours).</p><p>Cliquez sur la ligne d&#39;un élève pour ouvrir son <strong>aperçu</strong>, à droite de la liste sur un grand écran, ou en bas de l&#39;écran sur téléphone. L&#39;aperçu rassemble, sans quitter la liste : la classe et le site, les parents ou tuteurs rattachés avec leur adresse e-mail, la scolarité de l&#39;année (total payé et solde), l&#39;assiduité (absences, absences non justifiées, retards) et les trois dernières notes. Trois boutons y mènent directement : <strong>Modifier</strong>, <strong>Parents / tuteurs</strong> et <strong>Facturation</strong>.</p><p>Pour créer un élève :</p><ol><li>Cliquez sur <strong>Nouvel élève</strong>.</li><li>Renseignez le <strong>Prénom</strong> et le <strong>Nom de famille</strong>, puis, s&#39;ils sont connus, la <strong>Date de naissance</strong> et le <strong>Lieu de naissance</strong>. Si l&#39;établissement utilise le matricule, renseignez aussi le <strong>Matricule</strong> : deux élèves ne peuvent pas avoir le même. Tous ces champs sont facultatifs ; le matricule et le lieu de naissance figurent sur les relevés de notes et les attestations de réussite.</li><li>Choisissez une <strong>Classe</strong> pour l&#39;année scolaire en cours, ou laissez « Non affecté » pour créer le dossier sans inscription immédiate. La liste affiche l&#39;effectif de chaque classe et sa capacité.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Une classe <strong>complète</strong> n&#39;est pas refusée ici. Un avertissement s&#39;affiche avec un champ <strong>Motif du dépassement (facultatif)</strong> : l&#39;inscription passe, le dépassement est enregistré (il apparaît dans les <a href="/era-guide/guide/direction/pilotage.html">classes en sureffectif du pilotage</a>) et la direction du site en est informée.</p><p>En modifiant un élève, vous retrouvez les mêmes champs, à une différence près pour la classe. Un élève <strong>sans classe</strong> sur l&#39;année en cours peut y être inscrit directement. Un élève <strong>déjà inscrit</strong> voit sa classe affichée avec un bouton <strong>Changer de classe</strong> : le déplacement passe par un <a href="/era-guide/guide/secretariat/changements-de-classe.html">changement de classe</a>, qui vérifie le site et la capacité et garde une trace du motif. La fiche ne retire jamais un élève de sa classe, puisque son inscription porte ses paiements et ses bulletins.</p><p>La fiche affiche aussi deux tableaux en lecture seule si l&#39;élève a de l&#39;historique :</p><ul><li><strong>Historique des inscriptions</strong> — les classes suivies sur les années scolaires précédentes.</li><li><strong>Historique de référentiel</strong> — chaque passage de l&#39;élève d&#39;une classe à une autre en cours d&#39;année (changement de classe, transfert de site), avec la date, l&#39;auteur, et le département et le site de chaque classe : un changement de référentiel pédagogique (français ↔ togolais) s&#39;y lit donc aussi.</li></ul><h2 id="depart-d-un-eleve-en-cours-d-annee" tabindex="-1">Départ d&#39;un élève en cours d&#39;année <a class="header-anchor" href="#depart-d-un-eleve-en-cours-d-annee" aria-label="Permalink to &quot;Départ d&#39;un élève en cours d&#39;année&quot;">​</a></h2><p>Un élève n&#39;est <strong>jamais supprimé</strong> : son dossier porte ses notes, ses bulletins, ses paiements et son historique. Quand un élève quitte l&#39;établissement en cours d&#39;année (déménagement, changement d&#39;école…), enregistrez son départ depuis sa fiche, section <strong>Départ de l&#39;établissement</strong> :</p><ol><li>Renseignez la <strong>Date du départ</strong> (aujourd&#39;hui par défaut).</li><li>Écrivez le <strong>Motif</strong>.</li><li>Cliquez sur <strong>Enregistrer le départ</strong>.</li></ol><p>À partir de là :</p><ul><li>l&#39;élève disparaît des listes de classe, des appels, des feuilles de notes, de la publication des bulletins, des décisions de fin d&#39;année et des réinscriptions ;</li><li>il ne compte plus dans l&#39;effectif de sa classe : sa place est libérée ;</li><li>son lit d&#39;internat et sa place dans le bus sont libérés ;</li><li>il reste dans la liste des élèves, grisé, avec la mention « Parti le… » ;</li><li>la caisse le voit toujours, avec la même mention : ce qu&#39;il doit reste dû.</li></ul><p>Si l&#39;élève était déjà inscrit pour l&#39;année suivante, cette inscription est marquée partie elle aussi. Un départ enregistré par erreur s&#39;annule avec <strong>Annuler le départ</strong> : l&#39;élève revient dans sa classe. Son lit et sa place de bus, eux, ne lui sont pas rendus automatiquement : ils ont pu être attribués entre-temps.</p><p>Un élève qui revient plus tard dans l&#39;établissement est inscrit à nouveau, par une admission ou par sa fiche : son dossier est le même.</p><h2 id="ecrans-rattaches-a-la-fiche" tabindex="-1">Écrans rattachés à la fiche <a class="header-anchor" href="#ecrans-rattaches-a-la-fiche" aria-label="Permalink to &quot;Écrans rattachés à la fiche&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, trois boutons ouvrent des écrans dédiés : <strong>Matières de spécialité</strong>, <strong>Tuteurs</strong> et <strong>Compte élève</strong> (détaillés ci-dessous).</p><h2 id="tuteurs-parents" tabindex="-1">Tuteurs (parents) <a class="header-anchor" href="#tuteurs-parents" aria-label="Permalink to &quot;Tuteurs (parents)&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Tuteurs</strong> pour gérer les personnes qui ont accès au portail parent pour cet élève.</p><p>Pour ajouter un tuteur :</p><ol><li>Cliquez sur <strong>Ajouter un tuteur</strong>.</li><li>Renseignez le <strong>Nom</strong>, l&#39;<strong>E-mail</strong>, le <strong>Lien de parenté</strong> (Père, Mère, Tuteur légal ou Autre), et cochez <strong>Contact principal</strong> si c&#39;est le contact de référence.</li><li>Répétez pour chaque tuteur supplémentaire (bouton <strong>Retirer</strong> pour en supprimer un du formulaire).</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><p>Chaque tuteur ainsi rattaché a accès au portail parent pour cet élève et pour tous les autres élèves auxquels il est rattaché par ailleurs.</p><h2 id="compte-eleve-portail-eleve" tabindex="-1">Compte élève (portail élève) <a class="header-anchor" href="#compte-eleve-portail-eleve" aria-label="Permalink to &quot;Compte élève (portail élève)&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Compte élève</strong>. Un accès personnel au portail élève n&#39;est possible que pour un élève inscrit au lycée ou au-delà — pour les autres, la page affiche un message d&#39;inéligibilité et rien d&#39;autre.</p><p>Pour un élève éligible :</p><ul><li><strong>Créer le compte</strong> — renseignez une adresse e-mail, cliquez sur <strong>Créer le compte</strong>. L&#39;élève reçoit un e-mail d&#39;accueil avec un lien pour choisir son mot de passe (valable 60 minutes ; passé ce délai, « Mot de passe oublié ? » sur la page de connexion).</li><li><strong>Mettre à jour l&#39;e-mail</strong> — si un compte existe déjà, changez l&#39;adresse et cliquez sur <strong>Mettre à jour l&#39;e-mail</strong>.</li><li><strong>Révoquer l&#39;accès</strong> — supprime l&#39;accès personnel de l&#39;élève sans toucher à son dossier.</li></ul><h2 id="matieres-de-specialite" tabindex="-1">Matières de spécialité <a class="header-anchor" href="#matieres-de-specialite" aria-label="Permalink to &quot;Matières de spécialité&quot;">​</a></h2><p>Depuis la fiche d&#39;un élève, cliquez sur <strong>Matières de spécialité</strong>. Cet écran n&#39;affiche quelque chose que si l&#39;élève a une inscription active et que son département a des matières marquées « de spécialité » (voir <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>).</p><p>Pour chaque matière de spécialité proposée :</p><ol><li>Cochez la case pour la sélectionner pour cet élève.</li><li>Renseignez, si besoin, un <strong>coefficient</strong> personnalisé qui remplace celui défini par défaut au niveau du département — sinon le coefficient par défaut du département s&#39;applique.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol>',33)])])}const m=s(i,[["render",n]]);export{g as __pageData,m as default};
